15	 */
16	@Repository
17	public class ReviewRepository {
18	
19	    private final JdbcTemplate jdbc;
20	
21	    public ReviewRepository(JdbcTemplate jdbc) {
22	        this.jdbc = jdbc;
23	    }
24	
25	    private static final RowMapper<ReviewPo> REVIEW_MAPPER = (rs, n) -> new ReviewPo(
26	            rs.getString("review_id"),
27	            rs.getString("route_id"),
28	            rs.getInt("route_version"),
29	            rs.getLong("airspace_version"),
30	            rs.getString("conclusion"),
31	            decodeZoneIds(rs.getString("hit_zone_ids")),
32	            decodePoints(rs.getString("points_snapshot")),
33	            rs.getString("request_id"),
34	            rs.getLong("created_at"));
35	
36	    /** 按 reviewId 查询不可变审核记录，不存在返回 null。 */
37	    public ReviewPo findReview(String reviewId) {
38	        return jdbc.query(
39	                "SELECT review_id, route_id, route_version, airspace_version, conclusion, "
40	                        + "hit_zone_ids, points_snapshot, request_id, created_at "
41	                        + "FROM review WHERE review_id = ?",
42	                REVIEW_MAPPER, reviewId).stream().findFirst().orElse(null);
43	    }
44	
45	    /** 查询某航线最新的一条审核记录（按创建时间、reviewId 倒序），没有返回 null。 */
46	    public ReviewPo findLatestReview(String routeId) {
47	        return jdbc.query(
48	                "SELECT review_id, route_id, route_version, airspace_version, conclusion, "
49	                        + "hit_zone_ids, points_snapshot, request_id, created_at "
50	                        + "FROM review WHERE route_id = ? "
51	                        + "ORDER BY created_at DESC, review_id DESC LIMIT 1",
52	                REVIEW_MAPPER, routeId).stream().findFirst().orElse(null);
53	    }
54	
55	    /** 插入不可变审核结果（调用方负责事务）。 */
56	    public void insertReview(ReviewPo po) {
57	        jdbc.update("INSERT INTO review "
58	                        + "(review_id, route_id, route_version, airspace_version, conclusion, "
59	                        + "hit_zone_ids, points_snapshot, request_id, created_at) "
60	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
61	                po.reviewId(), po.routeId(), po.routeVersion(), po.airspaceVersion(),
62	                po.conclusion(), encodeZoneIds(po.hitZoneIds()), encodePoints(po.pointsSnapshot()),
63	                po.requestId(), po.createdAt());
64	    }
65	
66	    /** 查询幂等去重记录，不存在返回 null。 */
67	    public DedupPo findDedup(String requestId) {
68	        return jdbc.query(
69	                "SELECT request_id, request_kind, request_hash, response_json, created_at "
70	                        + "FROM request_dedup WHERE request_id = ?",
71	                (rs, n) -> new DedupPo(rs.getString("request_id"), rs.getString("request_kind"),
72	                        rs.getString("request_hash"), rs.getString("response_json"),
73	                        rs.getLong("created_at")),
74	                requestId).stream().findFirst().orElse(null);
75	    }
76	
77	    /** 插入幂等去重记录（与业务变更在同一事务提交）。 */
78	    public void insertDedup(DedupPo po) {
79	        jdbc.update("INSERT INTO request_dedup "
80	                        + "(request_id, request_kind, request_hash, response_json, created_at) "
81	                        + "VALUES (?, ?, ?, ?, ?)",
82	                po.requestId(), po.requestKind(), po.requestHash(), po.responseJson(), po.createdAt());
83	    }
84	
85	    /** 点列表编码："x,y;x,y"；空列表编码为空串。 */
86	    public static String encodePoints(List<Point> points) {
87	        StringBuilder sb = new StringBuilder();
88	        for (int i = 0; i < points.size(); i++) {
89	            if (i > 0) {
90	                sb.append(';');
91	            }
92	            sb.append(points.get(i).x()).append(',').append(points.get(i).y());
93	        }
94	        return sb.toString();
95	    }
96	
97	    /** 点列表解码。 */
98	    public static List<Point> decodePoints(String text) {
99	        List<Point> points = new ArrayList<>();
100	        if (text != null && !text.isEmpty()) {
101	            for (String pair : text.split(";")) {
102	                String[] xy = pair.split(",");
103	                points.add(new Point(Integer.parseInt(xy[0]), Integer.parseInt(xy[1])));
104	            }
105	        }
106	        return points;
107	    }
108	
109	    /** zoneId 列表编码（字典序去重由调用方保证），逗号拼接。 */
110	    public static String encodeZoneIds(List<String> zoneIds) {
111	        return String.join(",", zoneIds);
112	    }
113	
114	    /** zoneId 列表解码，空串返回空列表。 */
115	    public static List<String> decodeZoneIds(String text) {
116	        if (text == null || text.isEmpty()) {
117	            return new ArrayList<>();
118	        }
119	        return new ArrayList<>(Arrays.asList(text.split(",")));
120	    }
121	}
