package com.example.starter.api.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 登记圆形障碍请求。圆心为平面米坐标，半径为非负整数米；档案版本从 1 起。
 *
 * @param obstacleId 障碍唯一标识
 * @param cx         圆心 X 坐标（米）
 * @param cy         圆心 Y 坐标（米）
 * @param radius     障碍半径（非负整数米）
 * @param operator   操作者标识（可选），参与幂等身份的结构化比较
 * @param requestId  写操作全局唯一请求标识，用于幂等重放
 */
public record ObstacleCreateRequest(
        @NotBlank @Size(max = 64) String obstacleId,
        @NotNull @Min(-100000) @Max(100000) Integer cx,
        @NotNull @Min(-100000) @Max(100000) Integer cy,
        @NotNull @Min(0) @Max(100000) Integer radius,
        @Size(max = 64) String operator,
        @NotBlank @Size(max = 64) String requestId) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 修订圆形障碍请求。expectedVersion 为客户端期望的当前障碍版本，
 * 版本不匹配返回 409；成功后障碍版本加一并生成新版本，旧版本不可改。
 *
 * @param obstacleId      障碍唯一标识
 * @param expectedVersion 期望的当前障碍版本（版本从 1 开始）
 * @param cx              新圆心 X 坐标（米）
 * @param cy              新圆心 Y 坐标（米）
 * @param radius          新障碍半径（非负整数米）
 * @param operator        操作者标识（可选），参与幂等身份的结构化比较
 * @param requestId       写操作全局唯一请求标识，用于幂等重放
 */
public record ObstacleReviseRequest(
        @NotBlank @Size(max = 64) String obstacleId,
        @NotNull Integer expectedVersion,
        @NotNull @Min(-100000) @Max(100000) Integer cx,
        @NotNull @Min(-100000) @Max(100000) Integer cy,
        @NotNull @Min(0) @Max(100000) Integer radius,
        @Size(max = 64) String operator,
        @NotBlank @Size(max = 64) String requestId) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 撤销圆形障碍请求。expectedVersion 为客户端期望的当前障碍版本，
 * 版本不匹配返回 409；成功后障碍版本加一并置为 REVOKED，不再参与包络审查。
 *
 * @param obstacleId      障碍唯一标识
 * @param expectedVersion 期望的当前障碍版本（版本从 1 开始）
 * @param operator        操作者标识（可选），参与幂等身份的结构化比较
 * @param requestId       写操作全局唯一请求标识，用于幂等重放
 */
public record ObstacleRevokeRequest(
        @NotBlank @Size(max = 64) String obstacleId,
        @NotNull Integer expectedVersion,
        @Size(max = 64) String operator,
        @NotBlank @Size(max = 64) String requestId) {
}

package com.example.starter.api.dto;

/**
 * 圆形障碍登记/修订/撤销结果。
 *
 * @param obstacleId      障碍标识
 * @param status          操作后状态：ACTIVE / REVOKED
 * @param version         操作后的障碍版本
 * @param airspaceVersion 操作后生效的全局空域版本
 */
public record ObstacleResult(String obstacleId, String status, int version,
                             long airspaceVersion) {
}

