    void largeCoordinatesRemainExact() {
        // 坐标上限附近的大数：线段 (-100000,0)-(100000,0)，圆心 (0,100000)，距离恰 100000
        assertTrue(Geometry.segmentWithinDistance(-100000, 0, 100000, 0, 0, 100000, 100000));
